const { setTimeout: delay } = require('node:timers/promises');

const isTransient = (error) =>
  error?.code === 'ETIMEDOUT' ||
  error?.code === 'ECONNRESET' ||
  error?.status === 408 ||
  error?.status === 429 ||
  (error?.status >= 500 && error?.status < 600);

exports.pay = async (gateway, payment) => {
  const { id: idempotencyKey, amount } = payment;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      // Own the retry budget here; SDK retries would multiply gateway attempts.
      return await gateway.charge(amount, { idempotencyKey, maxAttempts: 1 });
    } catch (error) {
      if (attempt === 2 || !isTransient(error)) throw error;
      await delay(5);
    }
  }
};

