const fs = require('node:fs');
const path = require('node:path');
const { parseArgs } = require('node:util');
try {
  const { values } = parseArgs({ options: { dir: { type: 'string' }, days: { type: 'string' }, 'dry-run': { type: 'boolean' } } });
  const days = Number(values.days);
  if (!/^\d+$/.test(values.days ?? '') || !Number.isSafeInteger(days) || days <= 0) {
    throw new Error('--days must be a positive integer number of days.');
  }
  if (!values.dir || !values.dir.trim()) {
    throw new Error('--dir must specify an existing directory, not a symlink.');
  }
  // Normalize trailing slashes before lstat so a directory symlink is rejected.
  const directory = path.resolve(values.dir);
  if (!fs.lstatSync(directory).isDirectory()) {
    throw new Error('--dir must specify an existing directory, not a file or symlink.');
  }
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  for (const name of fs.readdirSync(directory)) {
    const target = path.join(directory, name);
    const stat = fs.lstatSync(target);
    if (!stat.isDirectory() || stat.mtimeMs >= cutoff) continue;
    if (values['dry-run']) console.log(`Would remove ${target}`);
    else fs.rmSync(target, { recursive: true, force: true });
  }
} catch (error) {
  console.error(`prune: ${error.message}\nUsage: node prune.cjs --dir PATH --days N [--dry-run]`);
  process.exitCode = 1;
}

